#define KELLY_DECOMP_SAVELOAD_VTABLE
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_SAVELOAD_VTABLE

extern "C" int sprintf(char *, const char *, ...);
#define assert(x) ((void)0)
#define NUM_MEMORY_SLOTS 1

class GenericGameSaver {
public:
    static GenericGameSaver *instance;
    static GenericGameSaver *inst() { return instance; }
    stringx getNotEnoughRoomString(int, int);
    stringx getInsertCardString(int, int);
    stringx getCardString(int, int);
};

class Career { public: void init(); };
class GlobalDataClass { public: void init(); };
extern Career *g_career;
extern bool careerStarted;
extern GlobalDataClass globalCareerData;
extern stringx ksGlobalTextArray[];

__asm__(".equ _16GenericGameSaver$instance, 0x0042E5B8");
__asm__(".equ getNotEnoughRoomString__16GenericGameSaverii, 0x001E65A8");
__asm__(".equ getInsertCardString__16GenericGameSaverii, 0x001E6628");
__asm__(".equ getCardString__16GenericGameSaverii, 0x001E60F0");
__asm__(".equ init__6Career, 0x0025A4C0");
__asm__(".equ init__15GlobalDataClass, 0x002EFC10");
__asm__(".equ g_career, 0x00427C9C");
__asm__(".equ careerStarted, 0x003E7704");
__asm__(".equ globalCareerData, 0x004349B8");
__asm__(".equ ksGlobalTextArray, 0x003E0000");
__asm__(".equ sprintf, 0x003D38A8");

enum GlobalTextIds {
    GT_FE_MENU_SAVE_FAIL = 0x67c0 / 8,
    GT_FE_MENU_LOAD_FAIL = 0x67e0 / 8,
    GT_FE_MENU_DEL_FAIL = 0x67e8 / 8,
    GT_FE_MENU_FORM_FAIL = 0x67f0 / 8,
    GT_FE_MENU_NO_FILENAME = 0x6818 / 8,
    GT_FE_MENU_NOT_UNIQUE = 0x6820 / 8,
    GT_FE_MENU_ASK_FORMAT = 0x6830 / 8
};

enum SaveErrors {
    SE_NO_MEMORY_CARDS,
    SE_UNFORMAT,
    SE_NOT_ENOUGH_SPACE,
    SE_SAVE_ERROR,
    SE_LOAD_ERROR,
    SE_FORM_ERROR,
    SE_DELETE_ERROR,
    SE_UNIQUE_FILENAME,
    SE_NO_FILENAME
};

class SaveLoadFrontEnd;
class NamesMenu : public FEMultiMenu {
    char padding[0x1fc - sizeof(FEMultiMenu)];
    int active_card;
public:
    int ActiveCard() { return active_card; }
    void TurnPQLines(bool);
};
class DialogMenu : public FEMultiMenu {
public:
    enum { DM_TYPE_MNG, DM_TYPE_FMT, DM_TYPE_YES, DM_TYPE_OK, DM_TYPE_PROGRESS, DM_TYPE_EMPTY };
    void SetTypeAndMessage(int, stringx);
};

__asm__(".equ TurnPQLines__9NamesMenub, 0x0019ED70");
__asm__(".equ SetTypeAndMessage__10DialogMenuiG7stringx, 0x0019D608");

class SaveLoadFrontEnd : public FEMultiMenu {
    char pad0[0x329c - sizeof(FEMultiMenu)];
public:
    enum disp_states {
        DSTATE_LSD, DSTATE_LOAD, DSTATE_LOAD_PICK, DSTATE_LOAD_GLOBAL,
        DSTATE_LOADING_GLOBAL, DSTATE_LOADING, DSTATE_LOAD_DONE, DSTATE_SAVE,
        DSTATE_SAVE_GLOBAL, DSTATE_SAVE_NAME, DSTATE_SAVE_PICK, DSTATE_SAVING,
        DSTATE_SAVING_GLOBAL, DSTATE_SAVE_PHOTO, DSTATE_SAVING_PHOTO,
        DSTATE_SAVE_DONE, DSTATE_DELETE
    };
    enum type { SL_SAVE, SL_LOAD, SL_DELETE };
    int cur_type;
private:
    char pad1[0x32c4 - 0x32a0];
    int dstate;
    char pad2[0x32d4 - 0x32c8];
    bool error_thrown;
    char pad3[3];
    int current_error;
    int next_state;
    char pad4[0x32f4 - 0x32e0];
public:
    NamesMenu *NameMenu;
    void *KeyMenu;
    DialogMenu *dialogMenu;
    void StartError(int id);
    static stringx MakeStringMemCard(int active_card);
};

__asm__(".equ MakeStringMemCard__16SaveLoadFrontEndi, 0x0019C838");

void SaveLoadFrontEnd::StartError(int id)
{
    stringx message = "";
    char temp[100];
    int port = NameMenu->ActiveCard()==-1?-1:NameMenu->ActiveCard()/NUM_MEMORY_SLOTS;
    int slot = NameMenu->ActiveCard()==-1?-1:NameMenu->ActiveCard()%NUM_MEMORY_SLOTS;
    switch(id)
    {
    case SE_NOT_ENOUGH_SPACE:
        next_state = DSTATE_SAVE;
        message = GenericGameSaver::inst()->getNotEnoughRoomString(port, slot);
        break;
    case SE_NO_MEMORY_CARDS:
        if(dstate == DSTATE_LSD)
            next_state = (cur_type == SL_SAVE ? DSTATE_SAVE : (cur_type == SL_LOAD ? DSTATE_LOAD : DSTATE_DELETE));
        else next_state = dstate;
        message = GenericGameSaver::inst()->getInsertCardString(port, slot);
        break;
    case SE_UNFORMAT:
        next_state = DSTATE_SAVE;
        message = stringx(stringx::fmt, ksGlobalTextArray[GT_FE_MENU_ASK_FORMAT].c_str(), SaveLoadFrontEnd::MakeStringMemCard(NameMenu->ActiveCard()).c_str());
        break;
    case SE_SAVE_ERROR:
        next_state = DSTATE_SAVE;
        sprintf(temp, ksGlobalTextArray[GT_FE_MENU_SAVE_FAIL].c_str(), GenericGameSaver::inst()->getCardString(port, slot).c_str());
        message = temp;
        break;
    case SE_LOAD_ERROR:
        g_career->init();
        careerStarted = false;
        globalCareerData.init();
        next_state = DSTATE_LOAD;
        sprintf(temp, ksGlobalTextArray[GT_FE_MENU_LOAD_FAIL].c_str(), GenericGameSaver::inst()->getCardString(port, slot).c_str());
        message = temp;
        break;
    case SE_FORM_ERROR:
        next_state = DSTATE_LSD;
        sprintf(temp, ksGlobalTextArray[GT_FE_MENU_FORM_FAIL].c_str(), GenericGameSaver::inst()->getCardString(port, slot).c_str());
        message = temp;
        break;
    case SE_DELETE_ERROR:
        next_state = DSTATE_DELETE;
        sprintf(temp, ksGlobalTextArray[GT_FE_MENU_DEL_FAIL].c_str(), GenericGameSaver::inst()->getCardString(port, slot).c_str());
        message = temp;
        break;
    case SE_NO_FILENAME:
        next_state = DSTATE_SAVE_NAME;
        message = ksGlobalTextArray[GT_FE_MENU_NO_FILENAME];
        break;
    case SE_UNIQUE_FILENAME:
        next_state = DSTATE_SAVE_NAME;
        message = ksGlobalTextArray[GT_FE_MENU_NOT_UNIQUE];
        break;
    default: assert(0);
    }

    int type = DialogMenu::DM_TYPE_OK;
    if(id == SE_NO_MEMORY_CARDS)
        type = DialogMenu::DM_TYPE_EMPTY;
    else if( id == SE_UNFORMAT )
        type = DialogMenu::DM_TYPE_YES;
    dialogMenu->SetTypeAndMessage(type, message);
    MakeActive(dialogMenu);
    NameMenu->TurnPQLines(false);
    current_error = id;
    error_thrown = true;
}
